mapper.select:
SELECT last_read_seq
FROM conversation_member
WHERE conversation_id = #{conversationId}
  AND user_id <> #{userId}
LIMIT 1

mapper.update:
UPDATE conversation_member
SET last_read_seq = GREATEST(last_read_seq, #{lastReadSeq}),
    pushed_unread = 0
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}

UPDATE conversation_member
SET pushed_unread = 1
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
  AND pushed_unread = 0

UPDATE conversation_member
SET deleted_at = CURRENT_TIMESTAMP,
    last_read_seq = GREATEST(last_read_seq, #{lastReadSeq}),
    pushed_unread = 0
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}

UPDATE conversation_member
SET deleted_at = NULL
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
  AND deleted_at IS NOT NULL
